import Resemble from '@resemble/node';

Resemble.setApiKey(process.env.RESEMBLE_API_KEY!);

const projectUuid = process.env.RESEMBLE_PROJECT_UUID!;
const voiceUuid = process.env.RESEMBLE_VOICE_UUID!;

// Create an async clip (non-streaming)
const response = await Resemble.v2.clips.createAsync(projectUuid, {
  voice_uuid: voiceUuid,
  body: 'Hello, this is a test of Resemble AI voice synthesis.',
  is_public: false,
  is_archived: false,
  sample_rate: 44100,
  output_format: 'mp3',
  precision: 'PCM_16',
});

if (response.success) {
  const clipUuid = response.item.uuid;
  console.log('Clip created:', clipUuid);

  // Poll until complete (or use webhook callback_uri)
  let clip = response.item;
  while (!clip.audio_src) {
    await new Promise(r => setTimeout(r, 1000));
    const status = await Resemble.v2.clips.get(projectUuid, clipUuid);
    if (status.success) clip = status.item;
  }

  console.log('Audio URL:', clip.audio_src);
} else {
  console.error('Failed to create clip:', response.message);
}
